// thresholdsConfigPath 是每仓库阈值配置相对仓库根的路径（见 config/README.md）。
const thresholdsConfigPath = "config/thresholds.json"

// LowStockThreshold 返回这个仓库的低库存阈值。
//
// 每次调用都重新读 config/thresholds.json，运维改完文件就能生效，不需要重新构建
