// thresholdFor 取 warehouse 的阈值，配置里没有就回退到 DefaultLowStockThreshold。
func thresholdFor(warehouse string, thresholds map[string]int) int {
	if threshold, ok := thresholds[warehouse]; ok {
		return threshold
	}
	return DefaultLowStockThreshold
}

// loadThresholds 读取并解析 thresholds.json，返回「仓库名 -> 阈值」。
// 文件找不到、读不了或格式非法都返回 nil：此时所有仓库都走默认值。
func loadThresholds() map[string]int {
	path, ok := findThresholdsConfig()
	if !ok {
		return nil
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil
	}
	var thresholds map[string]int
	if err := json.Unmarshal(data, &thresholds); err != nil {
		return nil
	}
	return thresholds
}

// findThresholdsConfig 从当前工作目录向上找 config/thresholds.json。
//
// go test 会把工作目录设成包目录（inventory/），服务也可能从仓库根启动，
// 向上查找能让两种情形落到同一份配置。
func findThresholdsConfig() (string, bool) {
	dir, err := os.Getwd()
	if err != nil {
		return "", false
	}
	for {
		candidate := filepath.Join(dir, filepath.FromSlash(thresholdsConfigPath))
		if info, err := os.Stat(candidate); err == nil && !info.IsDir() {
			return candidate, true
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "", false
		}
		dir = parent
	}
}

