package inventory

import (
	"os"
	"path/filepath"
	"testing"
)

// 本文件是后加的行为测试，只覆盖「按仓库配阈值 + 热生效」。
// 原有的 stock_test.go 是冻结的验收基线，一个字节都不改。

// writeThresholdsConfig 在 dir/config/thresholds.json 写入配置内容。
func writeThresholdsConfig(t *testing.T, dir, content string) {
	t.Helper()
	configDir := filepath.Join(dir, "config")
	if err := os.MkdirAll(configDir, 0o755); err != nil {
		t.Fatalf("建配置目录失败: %v", err)
	}
	if err := os.WriteFile(filepath.Join(configDir, "thresholds.json"), []byte(content), 0o644); err != nil {
		t.Fatalf("写配置失败: %v", err)
	}
}

// useThresholdsDir 在仓库内建一个隔离目录并把工作目录切过去，返回其绝对路径。
// 这样向上查找 thresholds.json 会先命中隔离目录里的配置，测完由 cleanup 还原。
// 目录建在仓库内而不是 os.TempDir()，避免依赖运行环境的临时目录权限。
func useThresholdsDir(t *testing.T) string {
	t.Helper()
	original, err := os.Getwd()
	if err != nil {
		t.Fatalf("取工作目录失败: %v", err)
	}
	dir, err := os.MkdirTemp(".", "thresholds-test-")
	if err != nil {
		t.Fatalf("建隔离目录失败: %v", err)
	}
	dir, err = filepath.Abs(dir)
	if err != nil {
		t.Fatalf("取隔离目录绝对路径失败: %v", err)
	}
	if err := os.Chdir(dir); err != nil {
		t.Fatalf("切工作目录失败: %v", err)
	}
	t.Cleanup(func() {
		_ = os.Chdir(original)
		_ = os.RemoveAll(dir)
	})
	return dir
}

// useThresholdsConfig 建隔离目录并写好配置。
func useThresholdsConfig(t *testing.T, content string) string {
	t.Helper()
	dir := useThresholdsDir(t)
	writeThresholdsConfig(t, dir, content)
	return dir
}

func TestLowStockThresholdReadsPerWarehouseConfig(t *testing.T) {
	useThresholdsConfig(t, `{"xian": 10, "beijing": 3}`)

	if got := LowStockThreshold("xian"); got != 10 {
		t.Fatalf("LowStockThreshold(xian) = %d, 期望配置值 10", got)
	}
	if got := LowStockThreshold("beijing"); got != 3 {
		t.Fatalf("LowStockThreshold(beijing) = %d, 期望配置值 3", got)
	}
	if got := LowStockThreshold("chengdu"); got != DefaultLowStockThreshold {
		t.Fatalf("LowStockThreshold(chengdu) = %d, 未配置应回退默认 %d",
			got, DefaultLowStockThreshold)
	}
}

func TestConfigChangeTakesEffectWithoutRebuild(t *testing.T) {
	dir := useThresholdsConfig(t, `{"xian": 10}`)
	if got := LowStockThreshold("xian"); got != 10 {
		t.Fatalf("改配置前 xian = %d, 期望 10", got)
	}

	writeThresholdsConfig(t, dir, `{"xian": 2}`)
	if got := LowStockThreshold("xian"); got != 2 {
		t.Fatalf("改配置后 xian = %d, 期望 2：改文件应当即生效，不重新构建", got)
	}
}

func TestMissingOrBrokenConfigFallsBackToDefault(t *testing.T) {
	cases := map[string]string{
		"no-file":     "",                 // 隔离目录里没有配置
		"broken-json": `{"xian":`,         // 语法错误
		"wrong-type":  `{"xian": "ten"}`,  // 类型错误
	}
	for name, content := range cases {
		t.Run(name, func(t *testing.T) {
			if content == "" {
				useThresholdsDir(t)
			} else {
				useThresholdsConfig(t, content)
			}
			if got := LowStockThreshold("xian"); got != DefaultLowStockThreshold {
				t.Fatalf("坏配置下 LowStockThreshold(xian) = %d, 期望默认 %d",
					got, DefaultLowStockThreshold)
			}
		})
	}
}

func TestLowStockWarehousesUsesPerWarehouseConfig(t *testing.T) {
	useThresholdsConfig(t, `{"xian": 10}`)

	got := LowStockWarehouses(map[string]int{"xian": 7, "beijing": 7})
	// xian 配成 10，7 < 10 是低库存；beijing 未配置，默认 5，7 不是。
	if len(got) != 1 || got[0] != "xian" {
		t.Fatalf("LowStockWarehouses = %v, 期望 [xian]", got)
	}
}
